sys_script_include.script:
var FuhrparkUtils = Class.create();
FuhrparkUtils.prototype = {
    initialize: function() {
    },
	validateDriverLicenseForVehicle: function(userId, vehicleId) {
        if (!userId || !vehicleId) return false;

        var vehicleGR = new GlideRecord('x_1794162_fuhrpark_vehicle');
        if (!vehicleGR.get(vehicleId)) return false;

        var requiredClass = vehicleGR.vehicle_model.driver_license_class;
        if (!requiredClass) return false;

        var dlGR = new GlideRecord('x_1794162_fuhrpark_driving_license');
        dlGR.addQuery('owner', userId);
        dlGR.addQuery('driving_license_class', requiredClass);
        dlGR.query();

        return dlGR.hasNext();
    },


    type: 'FuhrparkUtils'
};
